let data=window.__DATA__||{};
data={patients:[],bp:[],meds:[],intakes:[],settings:{},lastBackup:null,...data};
['patients','bp','meds','intakes'].forEach(k=>{if(!Array.isArray(data[k]))data[k]=[]});
let tab='home',pid=null,toastT=0;
