/* ---- clasificare (ESC/ESH 2018, orientativ) ---- */
const CATS=[
 {k:'low',n:'Tensiune mică',c:'#4f8cff',d:'Sub 90 / 60 mmHg. Dacă ai amețeli sau leșin, anunță medicul.'},
 {k:'opt',n:'Optimă',c:'#16a37a',d:'Sub 120 / 80 mmHg.'},
 {k:'norm',n:'Normală',c:'#4cb782',d:'120–129 / 80–84 mmHg.'},
 {k:'hn',n:'Normal-înaltă',c:'#d9a50f',d:'130–139 / 85–89 mmHg.'},
 {k:'g1',n:'Hipertensiune gr. 1',c:'#f08c2e',d:'140–159 / 90–99 mmHg.'},
 {k:'g2',n:'Hipertensiune gr. 2',c:'#e5484d',d:'160–179 / 100–109 mmHg.'},
 {k:'g3',n:'Hipertensiune gr. 3',c:'#a3172a',d:'180 / 110 mmHg sau peste.'}];
const lv=(x,a)=>a.filter(t=>x>=t).length,
catIdx=(s,d)=>{const i=Math.max(lv(s,[120,130,140,160,180])+1,lv(d,[80,85,90,100,110])+1);return i===1&&(s<90||d<60)?0:i},
catOf=(s,d)=>CATS[catIdx(s,d)],isCrisis=x=>x.sys>=180||x.dia>=120,
bpAt=x=>dts(x.date,x.time),
pbp=(p,from='0000-00-00',to='9999-12-31')=>data.bp.filter(x=>x.pid===p&&x.date>=from&&x.date<=to).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),
tgt=p=>({sys:+(P(p)?.sys)||130,dia:+(P(p)?.dia)||80}),
inTgt=(x,p)=>{const t=tgt(p);return x.sys<t.sys&&x.dia<t.dia},
BUCK=[['Dimineața','05:00–10:59',5,11],['Ziua','11:00–16:59',11,17],['Seara','17:00–22:59',17,23],['Noaptea','23:00–04:59',23,29]],
buck=t=>{let h=+t.slice(0,2);if(h<5)h+=24;return BUCK.findIndex(b=>h>=b[2]&&h<b[3])};
function bpStats(a,p){const n=a.length,s=a.map(x=>x.sys),d=a.map(x=>x.dia),pl=a.map(x=>+x.pulse).filter(Boolean);
 return{n,sys:avg(s),dia:avg(d),pulse:avg(pl),pn:pl.length,smin:n?Math.min(...s):0,smax:n?Math.max(...s):0,dmin:n?Math.min(...d):0,dmax:n?Math.max(...d):0,sdS:sd(s),
 inT:a.filter(x=>inTgt(x,p)).length,hi:a.filter(x=>x.sys>=140||x.dia>=90).length,crisis:a.filter(isCrisis).length,low:a.filter(x=>catIdx(x.sys,x.dia)===0).length,
 cats:CATS.map((c,i)=>a.filter(x=>catIdx(x.sys,x.dia)===i).length),days:new Set(a.map(x=>x.date)).size}}
/* ---- doze și aderență ---- */
const GRACE=60,
activeOn=(m,d)=>!m.prn&&d>=(m.start||'0000-00-00')&&(!m.end||d<=m.end)&&(!m.days||!m.days.length||m.days.includes(dow(d))),
slotsOn=(p,d)=>{const o=[];data.meds.filter(m=>m.pid===p).forEach(m=>{if(activeOn(m,d))(m.times||[]).forEach(t=>o.push({m,d,t}))});return o.sort((a,b)=>a.t.localeCompare(b.t)||a.m.name.localeCompare(b.m.name))},
intakeOf=s=>data.intakes.find(i=>i.medId===s.m.id&&i.date===s.d&&i.slot===s.t),
state=(s,now=new Date())=>{const i=intakeOf(s);if(i)return i.status;if(s.m.from&&s.d+'T'+s.t<s.m.from)return'na';const df=(now-dts(s.d,s.t))/6e4;return df<-30?'up':df<=GRACE?'due':'miss'};
function adh(p,from,to,medId){const t=today(),end=to<t?to:t,r={exp:0,taken:0,skip:0,miss:0,ontime:0,dl:[],by:{},slot:{},days:{}};
 for(let d=from;d<=end;d=addD(d,1)){let all=0,ok=0;for(const s of slotsOn(p,d)){if(medId&&s.m.id!==medId)continue;const st=state(s);if(st==='up'||st==='na'||st==='due')continue;
  r.exp++;all++;const b=r.by[s.m.id]=r.by[s.m.id]||{exp:0,taken:0,skip:0,miss:0},sl=r.slot[s.t]=r.slot[s.t]||{exp:0,taken:0,dl:[]};b.exp++;sl.exp++;
  if(st==='taken'){r.taken++;b.taken++;sl.taken++;ok++;const i=intakeOf(s);if(i&&i.at){let df=mins(i.at)-mins(s.t);if(df<-720)df+=1440;if(df>720)df-=1440;r.dl.push(df);sl.dl.push(df);if(Math.abs(df)<=GRACE)r.ontime++}}
  else if(st==='skipped'){r.skip++;b.skip++}else{r.miss++;b.miss++}}
  if(all)r.days[d]=ok===all}
 r.pct=r.exp?r.taken/r.exp*100:null;return r}
function setIntake(s,status){const old=intakeOf(s);data.intakes=data.intakes.filter(i=>i!==old);if(status){data.intakes.push({id:id(),pid:s.m.pid,medId:s.m.id,date:s.d,slot:s.t,at:s.d===today()?nowT():s.t,status})}}
const ST={taken:['✔ Luată','good'],skipped:['Sărită','mid'],miss:['Ratată','hot'],due:['Acum','due'],up:['Urmează',''],na:['—','']};
/* ---- corelații TA ↔ pastile ---- */
function corr(p,from,to){const bps=pbp(p,from,to),ints=data.intakes.filter(i=>i.pid===p&&i.status==='taken'&&i.at).map(i=>dts(i.date,i.at)),B=[[0,2,'0–2 ore după pastilă'],[2,4,'2–4 ore'],[4,8,'4–8 ore'],[8,1e9,'peste 8 ore / fără pastilă']],g=B.map(()=>[]);
 bps.forEach(x=>{const t=bpAt(x);let best=1e9;ints.forEach(it=>{const h=(t-it)/36e5;if(h>=0&&h<best)best=h});const k=B.findIndex(b=>best>=b[0]&&best<b[1]);g[k].push(x)});
 const ad=adh(p,from,to),good=[],bad=[];bps.forEach(x=>{if(!(x.date in ad.days))return;(ad.days[x.date]?good:bad).push(x)});
 return{B,g,good,bad}}
/* ---- concluzii automate ---- */
function insights(p,from,to){const a=pbp(p,from,to),o=[],s=bpStats(a,p),pt=P(p),t=tgt(p);
 if(!a.length){o.push(['warn','Nu există măsurători în perioada aleasă.']);return o}
 const c=catOf(s.sys,s.dia);o.push([catIdx(s.sys,s.dia)<=3&&catIdx(s.sys,s.dia)>0?'good':'',`Media perioadei este <b>${r0(s.sys)}/${r0(s.dia)} mmHg</b> (${c.n.toLowerCase()}), din ${s.n} măsurători în ${s.days} zile.`]);
 const pc=r0(s.inT/s.n*100);o.push([pc>=70?'good':pc>=40?'':'warn',`<b>${pc}%</b> din măsurători sunt sub ținta ${t.sys}/${t.dia}.`]);
 if(s.n>=6){const h=Math.floor(a.length/2),m1=avg(a.slice(0,h).map(x=>x.sys)),m2=avg(a.slice(h).map(x=>x.sys)),df=m2-m1;if(Math.abs(df)>=5)o.push([df<0?'good':'warn',`Tendință: sistolica ${df<0?'a scăzut':'a crescut'} cu ~${r0(Math.abs(df))} mmHg între prima și a doua jumătate a perioadei.`]);else o.push(['','Tendință: valorile sunt stabile (diferență sub 5 mmHg între jumătăți).'])}
 const bk=BUCK.map((_,i)=>a.filter(x=>buck(x.time)===i)),mo=bk[0],ev=bk[2];if(mo.length>=3&&ev.length>=3){const d=avg(mo.map(x=>x.sys))-avg(ev.map(x=>x.sys));if(Math.abs(d)>=8)o.push(['',`Dimineața sistolica medie este cu ~${r0(Math.abs(d))} mmHg ${d>0?'mai mare':'mai mică'} decât seara.`])}
 if(s.n>=5&&s.sdS>=15)o.push(['warn',`Variabilitate mare a sistolicei (abatere standard ${r0(s.sdS)} mmHg). Merită discutat cu medicul.`]);
 if(s.crisis)o.push(['warn',`<b>${s.crisis}</b> ${s.crisis===1?'valoare':'valori'} ≥ 180/120 mmHg. Dacă se repetă sau apar simptome, contactează medicul urgent.`]);else if(s.hi)o.push(['warn',`${s.hi} ${s.hi===1?'valoare':'valori'} ≥ 140/90 mmHg în perioadă.`]);
 if(s.low)o.push(['warn',`${s.low} ${s.low===1?'valoare scăzută':'valori scăzute'} (sub 90/60). Anunță medicul dacă ai amețeli.`]);
 const ad=adh(p,from,to);if(ad.exp){const pc=r0(ad.pct);o.push([pc>=90?'good':pc>=75?'':'warn',`Aderență la tratament: <b>${pc}%</b> (${ad.taken} luate din ${ad.exp} programate${ad.miss?`, ${ad.miss} ratate`:''}).`]);
  const w=Object.entries(ad.by).filter(([,b])=>b.exp>=3).map(([i,b])=>[i,b.taken/b.exp]).sort((x,y)=>x[1]-y[1])[0];if(w&&w[1]<.8)o.push(['warn',`Cele mai multe doze ratate: <b>${esc(data.meds.find(m=>m.id===w[0])?.name||'?')}</b> (${r0(w[1]*100)}% luate).`])}
 const cr=corr(p,from,to);if(cr.good.length>=3&&cr.bad.length>=3){const d=avg(cr.bad.map(x=>x.sys))-avg(cr.good.map(x=>x.sys));if(Math.abs(d)>=5)o.push(['',`În zilele cu toate dozele luate, sistolica medie a fost ${r0(avg(cr.good.map(x=>x.sys)))}, iar în zilele cu doze ratate ${r0(avg(cr.bad.map(x=>x.sys)))} mmHg (diferență ${r0(Math.abs(d))}). Indicativ, nu dovedește o cauză.`])}
 const days=Math.round((dts(to)-dts(from))/864e5)+1,last=pbp(p).slice(-1)[0];if(last&&today()>last.date){const k=Math.round((dts(today())-dts(last.date))/864e5);if(k>=3)o.push(['warn',`Ultima măsurătoare a fost acum ${k} zile.`])}
 return o}

