/* Tensiunea Mea · ajutoare UI: dialog, toast, grafice SVG */
function toast(msg,undo){document.querySelector('.toast')?.remove();const t=document.createElement('div');t.className='toast';t.innerHTML=`<span>${esc(msg)}</span>`+(undo?'<button>Anulează</button>':'');document.body.appendChild(t);
 if(undo)t.querySelector('button').onclick=()=>{t.remove();undo()};clearTimeout(toastT);toastT=setTimeout(()=>t.remove(),undo?6000:2600)}
const snapData=()=>JSON.stringify(data),restoreData=j=>{const o=JSON.parse(j);Object.keys(data).forEach(k=>delete data[k]);Object.assign(data,o);if(!P())setPid(data.patients[0]?.id||null);save()};
function ask(title,fields,cb,okText='Salvează'){const d=document.createElement('dialog');
 const f=x=>{const v=x.v??'';if(x.t==='select')return`<label class="${x.w?'w':''}">${x.l}<select name="${x.n}">${x.o.map(([a,b])=>`<option value="${esc(a)}"${String(a)===String(v)?' selected':''}>${esc(b)}</option>`).join('')}</select></label>`;
  if(x.t==='area')return`<label class="w">${x.l}<textarea name="${x.n}" rows="2">${esc(v)}</textarea></label>`;
  if(x.t==='days')return`<div class="w"><small class="mu">${x.l}</small><div class="seg dseg" style="margin-top:6px">${DORD.map(i=>`<label class="dchk"><input type="checkbox" name="d${i}"${(v||[0,1,2,3,4,5,6]).includes(i)?' checked':''}><span>${DOWN[i]}</span></label>`).join('')}</div></div>`;
  if(x.t==='times'){const a=v||[];return`<div class="w"><small class="mu">${x.l}</small><div class="tms">${[0,1,2,3,4,5].map(i=>`<input type="time" name="t${i}" value="${a[i]||''}">`).join('')}</div></div>`}
  if(x.t==='check')return`<label class="w ckl"><input type="checkbox" name="${x.n}"${v?' checked':''}> <span>${x.l}</span></label>`;
  return`<label class="${x.w?'w':''}">${x.l}<input name="${x.n}" type="${x.t||'text'}" value="${esc(v)}"${x.step?` step="${x.step}"`:''}${x.min!=null?` min="${x.min}"`:''}${x.max!=null?` max="${x.max}"`:''}${x.im?` inputmode="${x.im}"`:''}${x.ph?` placeholder="${esc(x.ph)}"`:''}${x.req?' required':''}></label>`};
 d.innerHTML=`<form method="dialog"><h2>${esc(title)}</h2><div class="form">${fields.map(f).join('')}</div><div class="acts"><button type="button" class="btn s" value="x">Anulează</button><button class="btn">${okText}</button></div></form>`;
 document.body.appendChild(d);d.showModal();d.querySelector('[value=x]').onclick=()=>{d.close();d.remove()};
 d.querySelector('form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),v=Object.fromEntries(fd);v.days=DORD.filter(i=>fd.has('d'+i));v.times=[...new Set([0,1,2,3,4,5].map(i=>fd.get('t'+i)).filter(Boolean))].sort();
  fields.filter(x=>x.t==='check').forEach(x=>v[x.n]=fd.has(x.n));if(cb(v)===false)return;d.close();d.remove()};d.addEventListener('close',()=>d.remove())}
/* ---- grafice ---- */
const nice=(a,b)=>[Math.floor(a/10)*10,Math.ceil(b/10)*10];
function lineSvg({series,x0,x1,lines=[],y0,y1,h=230,xl=[],vl=[],xfmt,xlab}){const W=640,L=36,R=10,T=12,B=26,all=series.flatMap(s=>s.pts.map(p=>p[1])).concat(lines.map(l=>l.y));
 if(!all.length)return'';let[a,b]=nice(Math.min(...all)-4,Math.max(...all)+4);if(y0!=null)a=y0;if(y1!=null)b=y1;const X=x=>L+(x-x0)/Math.max(1,x1-x0)*(W-L-R),Y=y=>T+(1-(y-a)/(b-a))*(h-T-B);
 let s=`<svg viewBox="0 0 ${W} ${h}" class="ch" role="img">`;const st=b-a>80?20:10;for(let y=Math.ceil(a/st)*st;y<=b;y+=st)s+=`<line x1="${L}" x2="${W-R}" y1="${Y(y)}" y2="${Y(y)}" class="gl"/><text x="${L-6}" y="${Y(y)+4}" text-anchor="end" class="tl">${y}</text>`;
 xl.forEach(([x,t])=>{s+=`<text x="${X(x)}" y="${h-8}" text-anchor="middle" class="tl">${esc(t)}</text>`});
 vl.forEach(([x,t])=>{s+=`<line x1="${X(x)}" x2="${X(x)}" y1="${T}" y2="${h-B}" class="vl"/><text x="${X(x)+3}" y="${T+9}" class="tl vt">${esc(t)}</text>`});
 lines.forEach(l=>{s+=`<line x1="${L}" x2="${W-R}" y1="${Y(l.y)}" y2="${Y(l.y)}" stroke="${l.c}" stroke-dasharray="5 4" stroke-width="1.5"/><text x="${W-R}" y="${Y(l.y)-4}" text-anchor="end" class="tl" fill="${l.c}">${esc(l.t||'')}</text>`});
 series.forEach(se=>{if(se.line&&se.pts.length>1)s+=`<polyline fill="none" stroke="${se.c}" stroke-width="${se.w||2}" stroke-opacity="${se.o||.55}" stroke-linejoin="round" points="${se.pts.map(p=>X(p[0]).toFixed(1)+','+Y(p[1]).toFixed(1)).join(' ')}"/>`;
  const r=se.pts.length>120?2.2:se.r||4;se.pts.forEach(p=>{s+=`<circle cx="${X(p[0]).toFixed(1)}" cy="${Y(p[1]).toFixed(1)}" r="${r}" fill="${p[2]||se.c}" opacity="${se.po||1}"><title>${esc(p[3]||'')}</title></circle>`})});
 return s+'</svg>'}
const xTicks=(from,to,n=5)=>{const a=dts(from).getTime(),b=dts(to,'23:59').getTime(),o=[];for(let i=0;i<=n;i++){const t=a+(b-a)*i/n;o.push([t,fmtS(addD(from,Math.round((t-a)/864e5)))])}return o};
function bpChart(a,p,from,to){const t=tgt(p),x0=dts(from).getTime(),x1=dts(to,'23:59').getTime(),pt=x=>bpAt(x).getTime(),tt=x=>`${fmtD(x.date)} ${x.time} · ${x.sys}/${x.dia}`+(x.pulse?` · puls ${x.pulse}`:'');
 return lineSvg({x0,x1,xl:xTicks(from,to),lines:[{y:t.sys,c:'#16a37a',t:'țintă '+t.sys},{y:t.dia,c:'#16a37a',t:'țintă '+t.dia}],series:[{c:'#e5484d',line:1,pts:a.map(x=>[pt(x),x.sys,catOf(x.sys,x.dia).c,'Sistolică '+tt(x)])},{c:'#4f8cff',line:1,r:3,po:.85,pts:a.map(x=>[pt(x),x.dia,catOf(x.sys,x.dia).c,'Diastolică '+tt(x)])}]})}
function pulseChart(a,from,to){const b=a.filter(x=>+x.pulse);return lineSvg({x0:dts(from).getTime(),x1:dts(to,'23:59').getTime(),xl:xTicks(from,to),series:[{c:'#d946a8',line:1,pts:b.map(x=>[bpAt(x).getTime(),+x.pulse,null,`${fmtD(x.date)} ${x.time} · puls ${x.pulse}`])}],h:170})}
function hourChart(a,p){const sl=new Map();data.meds.filter(m=>m.pid===p&&!m.prn).forEach(m=>(m.times||[]).forEach(t=>sl.set(t,(sl.get(t)||0)+1)));
 return lineSvg({x0:0,x1:1440,xl:[0,4,8,12,16,20,24].map(h=>[h*60,h+':00']),vl:[...sl.keys()].map(t=>[mins(t),t]),series:[{c:'#e5484d',pts:a.map(x=>[mins(x.time),x.sys,catOf(x.sys,x.dia).c,`${fmtD(x.date)} ${x.time} · ${x.sys}/${x.dia}`])}]})}
const chip=c=>`<span class="chip" style="background:${c.c}22;color:${c.c}">${esc(c.n)}</span>`,
bpChip=x=>chip(catOf(x.sys,x.dia)),
pctCls=p=>p==null?'':p>=90?'ok':p>=75?'':'er',
bar=(p,c)=>`<div class="bar"><i style="width:${Math.max(0,Math.min(100,p||0))}%;${c?'background:'+c:''}"></i></div>`,
ago=(d,t)=>{const m=Math.round((Date.now()-dts(d,t).getTime())/6e4);if(m<1)return'chiar acum';if(m<60)return`acum ${m} min`;if(m<1440)return`acum ${Math.floor(m/60)} h`;const z=Math.floor(m/1440);return z===1?'ieri':`acum ${z} zile`},
dl=(name,txt,type)=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(a.href)},500)},
csvq=v=>'"'+String(v??'').replace(/"/g,'""')+'"';

