/* ===== src/reports.js ===== */
/* Tensiunea Mea · rapoarte pe pacient */
const R={tab:'sum',days:30,from:addD(today(),-29),to:today()};
const rng=()=>R.days?[addD(today(),-(R.days-1)),today()]:[R.from,R.to],
heat=(a,from,to)=>{const m={};a.forEach(x=>(m[x.date]=m[x.date]||[]).push(x));let h='';for(let d=from,n=0;d<=to&&n<400;d=addD(d,1),n++){const g=m[d],c=g?catOf(avg(g.map(x=>x.sys)),avg(g.map(x=>x.dia))):null;h+=`<i style="${c?`background:${c.c}`:''}" class="${c?'':'em'}" title="${fmtD(d)}${g?' · medie '+r0(avg(g.map(x=>x.sys)))+'/'+r0(avg(g.map(x=>x.dia))):' · fără măsurători'}">${+d.slice(8)}</i>`}return`<div class="heat">${h}</div>`},
heatA=(ad,from,to)=>{let h='';for(let d=from,n=0;d<=to&&n<400;d=addD(d,1),n++){const v=ad.days[d];h+=`<i style="${v===true?'background:#16a37a':v===false?'background:#e5484d':''}" class="${v==null?'em':''}" title="${fmtD(d)}${v==null?' · fără doze programate':v?' · toate dozele luate':' · doze ratate'}">${+d.slice(8)}</i>`}return`<div class="heat">${h}</div>`},
pct=(n,d)=>d?r0(n/d*100)+'%':'—';
function bpTable(a){return`<table class="tb"><tr><th>Data</th><th>Ora</th><th>TA</th><th>Puls</th><th>Încadrare</th></tr>${a.map(x=>`<tr><td>${fmtD(x.date)}</td><td>${x.time}</td><td><b>${x.sys}/${x.dia}</b></td><td>${x.pulse||''}</td><td>${esc(catOf(x.sys,x.dia).n)}</td></tr>`).join('')}</table>`}
function slotTable(p,from,to){const ad=adh(p,from,to);return`<table class="tb"><tr><th>Ora programată</th><th>Medicament</th><th>Luate</th><th>Ora medie reală</th></tr>${Object.keys(ad.slot).sort().map(t=>{const s=ad.slot[t],ms=data.meds.filter(m=>m.pid===p&&!m.prn&&(m.times||[]).includes(t));return`<tr><td><b>${t}</b></td><td>${ms.map(m=>esc(m.name)+' '+esc(m.dose||'')).join(', ')}</td><td>${pct(s.taken,s.exp)}</td><td>${s.dl.length?hm(mins(t)+avg(s.dl))+(Math.abs(avg(s.dl))>=15?` (${avg(s.dl)>0?'+':''}${r0(avg(s.dl))} min)`:''):'—'}</td></tr>`}).join('')||'<tr><td colspan="4" class="mu">Nu există doze programate în perioadă.</td></tr>'}</table>`}
const RT=[['sum','Rezumat'],['bp','Tensiune'],['med','Pastile'],['cor','Corelații'],['doc','Pentru medic'],['all','Toți pacienții']];
V.rep=()=>{if(!P())return onboard();const[from,to]=rng(),a=pbp(pid,from,to),p=P(),s=bpStats(a,pid),t=tgt(pid);
 const bar0=`<div class="seg sc noprint">${RT.map(([k,n])=>`<button class="${R.tab===k?'on':''}" data-rt="${k}">${n}</button>`).join('')}</div>${R.tab==='all'?'':`<div class="noprint" style="margin-top:8px"><div class="seg sc">${[[7,'7 zile'],[30,'30 zile'],[90,'90 zile'],[180,'6 luni'],[0,'Perioadă']].map(([d,n])=>`<button class="${R.days===d?'on':''}" data-rd="${d}">${n}</button>`).join('')}</div>${R.days?'':`<div class="form" style="margin-top:8px"><label>De la<input type="date" id="rf" value="${R.from}"></label><label>Până la<input type="date" id="rt" value="${R.to}"></label></div>`}</div>`}`;
 const head=`<div class="card">${bar0}<p class="mu" style="margin:12px 0 0">${esc(p.name)} · ${fmtD(from)} – ${fmtD(to)}</p></div>`;
 if(R.tab==='all'){const t0=today(),f=addD(t0,-29);return head+`<div class="card"><h2>Toți pacienții (ultimele 30 de zile)</h2><table class="tb"><tr><th>Pacient</th><th>Ultima</th><th>Medie</th><th>Sub țintă</th><th>Pastile</th></tr>${data.patients.map(q=>{const b=pbp(q.id,f,t0),st=bpStats(b,q.id),l=pbp(q.id).slice(-1)[0],ad=adh(q.id,f,t0);return`<tr><td><b>${esc(q.name)}</b></td><td>${l?l.sys+'/'+l.dia:'—'}</td><td>${st.n?r0(st.sys)+'/'+r0(st.dia):'—'}</td><td>${st.n?pct(st.inT,st.n):'—'}</td><td class="${pctCls(ad.pct)}">${ad.exp?r0(ad.pct)+'%':'—'}</td></tr>`}).join('')}</table></div>`}
 if(R.tab==='sum')return head+`<div class="grid"><div class="card kpi"><small>Media TA</small><b>${s.n?r0(s.sys)+'/'+r0(s.dia):'—'}</b></div><div class="card kpi"><small>Min – max sistolică</small><b>${s.n?s.smin+' – '+s.smax:'—'}</b></div><div class="card kpi"><small>Puls mediu</small><b>${s.pn?r0(s.pulse):'—'}</b></div><div class="card kpi"><small>Sub țintă ${t.sys}/${t.dia}</small><b>${s.n?pct(s.inT,s.n):'—'}</b></div></div>
<div class="card"><h2>Concluzii</h2><div class="ins">${insights(pid,from,to).map(([c,h])=>`<div class="in2 ${c}"><i>${c==='warn'?'!':c==='good'?'✓':'•'}</i><span>${h}</span></div>`).join('')}</div><small class="mu" style="display:block;margin-top:10px">Concluzii automate, orientative. ${DISC}</small></div>
<div class="card"><h2>Evoluția tensiunii</h2>${a.length?bpChart(a,pid,from,to):'<div class="empty">Fără date.</div>'}</div>
<div class="card"><h2>Distribuția valorilor</h2>${CATS.map((c,i)=>s.cats[i]?`<div style="margin:10px 0"><div class="row" style="border:0;padding:0"><span><i class="dot" style="background:${c.c}"></i>${c.n}</span><b>${s.cats[i]} (${pct(s.cats[i],s.n)})</b></div>${bar(s.cats[i]/s.n*100,c.c)}</div>`:'').join('')||'<div class="empty">Fără date.</div>'}<small class="mu">Clasificare orientativă ESC/ESH 2018 pentru măsurători în cabinet; ghidul ESC 2024 folosește 3 categorii (sub 120/70, 120–139/70–89, ≥140/90). Încadrarea finală o face medicul.</small></div>`;
 if(R.tab==='bp'){const bk=BUCK.map((b,i)=>[b,a.filter(x=>buck(x.time)===i)]),hi=[...a].sort((x,y)=>y.sys-x.sys).slice(0,3),lo=[...a].sort((x,y)=>x.sys-y.sys).slice(0,3);
 return head+`<div class="card"><h2>Tensiune în timp</h2>${a.length?bpChart(a,pid,from,to):'<div class="empty">Fără date.</div>'}<small class="mu">Culoarea punctelor arată încadrarea fiecărei măsurători. Liniile verzi sunt ținta.</small></div>
<div class="card"><h2>Puls</h2>${a.some(x=>+x.pulse)?pulseChart(a,from,to):'<div class="empty">Nu ai notat pulsul.</div>'}</div>
<div class="card"><h2>În funcție de momentul zilei</h2><table class="tb"><tr><th>Moment</th><th>Nr.</th><th>Medie</th><th>Sub țintă</th></tr>${bk.map(([b,g])=>`<tr><td>${b[0]}<small class="mu"> ${b[1]}</small></td><td>${g.length}</td><td>${g.length?r0(avg(g.map(x=>x.sys)))+'/'+r0(avg(g.map(x=>x.dia))):'—'}</td><td>${g.length?pct(g.filter(x=>inTgt(x,pid)).length,g.length):'—'}</td></tr>`).join('')}</table></div>
<div class="card"><h2>Calendar zilnic (media zilei)</h2>${heat(a,from,to)}<div class="leg2">${CATS.map(c=>`<span><i class="dot" style="background:${c.c}"></i>${c.n}</span>`).join('')}</div></div>
<div class="card"><h2>Valori extreme</h2>${a.length?`<b>Cele mai mari</b>${hi.map(x=>bpRow(x,false)).join('')}<b style="display:block;margin-top:12px">Cele mai mici</b>${lo.map(x=>bpRow(x,false)).join('')}`:'<div class="empty">Fără date.</div>'}</div>`}
 if(R.tab==='med'){const ad=adh(pid,from,to),ms=data.meds.filter(m=>m.pid===pid);
 return head+`<div class="grid"><div class="card kpi"><small>Aderență</small><b class="${pctCls(ad.pct)}">${ad.exp?r0(ad.pct)+'%':'—'}</b></div><div class="card kpi"><small>Doze luate</small><b>${ad.taken}/${ad.exp}</b></div><div class="card kpi"><small>Ratate</small><b class="${ad.miss?'er':''}">${ad.miss}</b></div><div class="card kpi"><small>La timp (±1 h)</small><b>${ad.taken?pct(ad.ontime,ad.taken):'—'}</b></div></div>
<div class="card"><h2>Pe medicament</h2>${ms.filter(m=>ad.by[m.id]).map(m=>{const b=ad.by[m.id];return`<div style="margin:12px 0"><div class="row" style="border:0;padding:0"><span>${esc(m.name)} <small style="display:inline">${esc(m.dose||'')}</small></span><b class="${pctCls(b.taken/b.exp*100)}">${pct(b.taken,b.exp)}</b></div>${bar(b.taken/b.exp*100)}<small class="mu">${b.taken} luate · ${b.skip} sărite · ${b.miss} ratate</small></div>`}).join('')||'<div class="empty">Nu există doze programate în perioadă.</div>'}</div>
<div class="card"><h2>Pe ore: programat vs. real</h2>${slotTable(pid,from,to)}<small class="mu">Ora medie reală = media orelor la care ai bifat pastila.</small></div>
<div class="card"><h2>Calendar aderență</h2>${heatA(ad,from,to)}<div class="leg2"><span><i class="dot" style="background:#16a37a"></i>toate luate</span><span><i class="dot" style="background:#e5484d"></i>cu doze ratate</span></div></div>`}
 if(R.tab==='cor'){const c=corr(pid,from,to);return head+`<div class="card"><h2>TA în funcție de ultima pastilă</h2>${c.B.map((b,i)=>{const g=c.g[i];return`<div class="row"><span>${b[2]}<small>${g.length} măsurători</small></span><b>${g.length>=2?r0(avg(g.map(x=>x.sys)))+'/'+r0(avg(g.map(x=>x.dia))):'—'}</b></div>`}).join('')}</div>
<div class="card"><h2>Zile cu toate dozele vs. cu doze ratate</h2><div class="row"><span>Toate dozele luate<small>${c.good.length} măsurători</small></span><b>${c.good.length?r0(avg(c.good.map(x=>x.sys)))+'/'+r0(avg(c.good.map(x=>x.dia))):'—'}</b></div><div class="row"><span>Cu doze ratate<small>${c.bad.length} măsurători</small></span><b>${c.bad.length?r0(avg(c.bad.map(x=>x.sys)))+'/'+r0(avg(c.bad.map(x=>x.dia))):'—'}</b></div></div>
<div class="card"><h2>Sistolica pe ore, cu orele pastilelor</h2>${a.length?hourChart(a,pid):'<div class="empty">Fără date.</div>'}<small class="mu">Liniile verticale marchează orele programate pentru pastile.</small></div><small class="mu">Comparațiile sunt orientative: pe puține măsurători nu arată o legătură de cauză. Discută cu medicul.</small>`}
 if(R.tab==='doc'){const ad=adh(pid,from,to),ms=data.meds.filter(m=>m.pid===pid&&(!m.end||m.end>=from)),dn=m=>!m.days||!m.days.length||m.days.length===7?'zilnic':DORD.filter(i=>m.days.includes(i)).map(i=>DOWN[i]).join(', ');
 return head+`<div class="card docr"><h1 style="font-size:22px;margin:0 0 4px">Raport tensiune arterială</h1><p style="margin:0 0 14px"><b>${esc(p.name)}</b>${p.born?' · născut '+fmtD(p.born):''}<br>Perioadă: ${fmtD(from)} – ${fmtD(to)} · generat ${fmtD(today())}</p>
<h2>Rezumat</h2><p>${s.n?`${s.n} măsurători în ${s.days} zile. Medie <b>${r0(s.sys)}/${r0(s.dia)}</b> mmHg (sistolică ${s.smin}–${s.smax}, diastolică ${s.dmin}–${s.dmax})${s.pn?`, puls mediu ${r0(s.pulse)}`:''}. Sub ținta ${t.sys}/${t.dia}: ${pct(s.inT,s.n)}. Valori ≥140/90: ${s.hi}, ≥180/120: ${s.crisis}, sub 90/60: ${s.low}.`:'Nu există măsurători.'}</p>
${a.length?bpChart(a,pid,from,to):''}<h2>Tratament</h2><table class="tb"><tr><th>Medicament</th><th>Doză</th><th>Ore</th><th>Zile</th><th>Luate</th></tr>${ms.map(m=>{const b=ad.by[m.id];return`<tr><td>${esc(m.name)}</td><td>${esc(m.dose||'')}</td><td>${m.prn?'la nevoie':(m.times||[]).join(', ')}</td><td>${m.prn?'—':dn(m)}</td><td>${b?pct(b.taken,b.exp):'—'}</td></tr>`}).join('')||'<tr><td colspan="5">Fără medicamente.</td></tr>'}</table><p>Aderență generală: <b>${ad.exp?r0(ad.pct)+'%':'—'}</b> (${ad.taken} luate, ${ad.skip} sărite, ${ad.miss} ratate).</p>
<h2>Măsurători</h2>${a.length?bpTable(a):'<p>Fără măsurători.</p>'}<p class="mu" style="font-size:12px">${DISC} Încadrare orientativă ESC/ESH 2018.</p></div>
<div class="card noprint"><div class="acts2"><button class="btn" data-act="print">Tipărește / salvează PDF</button><button class="btn s" data-act="csvbp">CSV tensiune</button><button class="btn s" data-act="csvin">CSV pastile</button></div></div>`}};

/* ===== src/main.js ===== */
/* Tensiunea Mea · evenimente, formulare, export, pornire */
let _rd=false,_rq=false;
function render(){if(_rd){_rq=true;return}_rd=true;try{renderNow()}finally{_rd=false}if(_rq){_rq=false;render()}}
function renderNow(){$('nav').innerHTML=NAV.map(([k,n])=>`<button class="nb ${tab===k?'on':''}" data-go="${k}"><span class="nic">${ICON[k]}</span>${n}</button>`).join('');
 $('title').textContent=NAV.find(n=>n[0]===tab)[1];const ps=$('psel');ps.innerHTML=data.patients.map(p=>`<option value="${p.id}"${p.id===pid?' selected':''}>${esc(p.name)}</option>`).join('');ps.hidden=data.patients.length<1;
 document.querySelector('header .btn').hidden=document.querySelector('.fab').hidden=!P();$('view').innerHTML=V[tab]();document.body.classList.remove('open')}
const num=v=>v===''||v==null?null:Number(v),
bpFields=x=>[{n:'sys',l:'Sistolică',t:'number',v:x.sys,req:1,im:'numeric'},{n:'dia',l:'Diastolică',t:'number',v:x.dia,req:1,im:'numeric'},{n:'pulse',l:'Puls',t:'number',v:x.pulse||'',im:'numeric'},{n:'date',l:'Data',t:'date',v:x.date,req:1},{n:'time',l:'Ora',t:'time',v:x.time,req:1},{n:'arm',l:'Braț',t:'select',v:x.arm,o:[['st','Stâng'],['dr','Drept']]},{n:'pos',l:'Poziție',t:'select',v:x.pos,o:[['sed','Șezând'],['cul','Culcat'],['pic','În picioare']]},{n:'note',l:'Notă',v:x.note||'',w:1}];
function bpOk(v){const s=+v.sys,d=+v.dia,p=v.pulse===''||v.pulse==null?null:+v.pulse;if(!(s>=50&&s<=300&&d>=30&&d<=200)){alert('Valori nerealiste. Sistolica trebuie să fie 50–300 și diastolica 30–200.');return false}if(s<=d){alert('Sistolica (mare) trebuie să fie mai mare decât diastolica (mică).');return false}if(p!=null&&!(p>=20&&p<=250)){alert('Pulsul trebuie să fie între 20 și 250.');return false}return true}
const bpObj=v=>({sys:+v.sys,dia:+v.dia,pulse:v.pulse?+v.pulse:null,date:v.date,time:v.time,arm:v.arm,pos:v.pos,note:(v.note||'').trim()});
const patFields=p=>[{n:'name',l:'Nume',v:p.name||'',req:1,w:1},{n:'born',l:'Data nașterii',t:'date',v:p.born||''},{n:'sys',l:'Țintă sistolică',t:'number',v:p.sys||130,im:'numeric'},{n:'dia',l:'Țintă diastolică',t:'number',v:p.dia||80,im:'numeric'},{n:'times',l:'Ore memento măsurare (pentru .ics)',t:'times',v:p.remind||[]},{n:'notes',l:'Note (ex. afecțiuni, medic)',t:'area',v:p.notes||''}];
function savePat(p,v){p.name=v.name.trim();p.born=v.born||'';p.sys=Math.min(180,Math.max(90,+v.sys||130));p.dia=Math.min(110,Math.max(50,+v.dia||80));p.remind=v.times||[];p.notes=v.notes||''}
function medForm(m){const o=m||{};ask(m?'Editează medicamentul':'Medicament nou',[{n:'name',l:'Denumire',v:o.name||'',req:1,w:1,ph:'ex. Amlodipină'},{n:'dose',l:'Doză',v:o.dose||'',ph:'ex. 5 mg'},{n:'prn',l:'Doză la nevoie (fără ore fixe)',t:'check',v:o.prn},{n:'times',l:'Ore (până la 6)',t:'times',v:o.times||['08:00']},{n:'days',l:'Zile',t:'days',v:o.days&&o.days.length?o.days:null},{n:'start',l:'Începe la',t:'date',v:o.start||today()},{n:'end',l:'Se oprește la (opțional)',t:'date',v:o.end||''},{n:'note',l:'Notă',v:o.note||'',w:1}],v=>{
 if(!v.name.trim())return false;if(!v.prn&&!v.times.length){alert('Alege cel puțin o oră sau bifează „la nevoie”.');return false}if(v.end&&v.end<v.start){alert('Data de oprire este înaintea datei de început.');return false}
 const t=today(),days=v.days.length===7||!v.days.length?[]:v.days,times=v.prn?[]:v.times,x=m||{id:id(),pid};const ch=!m||JSON.stringify(x.times)!==JSON.stringify(times)||x.start!==v.start;
 Object.assign(x,{name:v.name.trim(),dose:v.dose.trim(),prn:!!v.prn,times,days,start:v.start,end:v.end||'',note:v.note.trim()});if(ch)x.from=v.start<t?v.start+'T00:00':t+'T'+nowT();if(!m)data.meds.push(x);save()})}
function icsText(){const p=P(),t=today(),L=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Tensiunea Mea//RO','CALSCALE:GREGORIAN'],z=s=>s.replace(/-/g,''),dt=(d,h)=>z(d)+'T'+h.replace(':','')+'00',BD=['SU','MO','TU','WE','TH','FR','SA'];
 const ev=(sum,h,days,start,end,desc)=>{let d=start>t?start:t;for(let i=0;i<7&&days.length&&!days.includes(dow(d));i++)d=addD(d,1);
  L.push('BEGIN:VEVENT','UID:'+id()+'@tensiunea-mea','DTSTAMP:'+z(t)+'T000000','DTSTART:'+dt(d,h),'DTEND:'+dt(d,hm(mins(h)+10)),'RRULE:FREQ='+(days.length?'WEEKLY;BYDAY='+days.map(i=>BD[i]).join(','):'DAILY')+(end?';UNTIL='+z(end)+'T235959':''),'SUMMARY:'+sum,'DESCRIPTION:'+desc,'BEGIN:VALARM','TRIGGER:PT0M','ACTION:DISPLAY','DESCRIPTION:'+sum,'END:VALARM','END:VEVENT')};
 data.meds.filter(m=>m.pid===pid&&!m.prn&&(!m.end||m.end>=t)).forEach(m=>(m.times||[]).forEach(h=>ev('💊 '+m.name+' '+(m.dose||'')+' ('+p.name+')',h,m.days||[],m.start||t,m.end,'Pastilă programată')));
 (p.remind||[]).forEach(h=>ev('❤️ Măsoară tensiunea ('+p.name+')',h,[],t,'','Măsurare tensiune'));L.push('END:VCALENDAR');return L.join('\r\n')}
function validate(j){if(!j||typeof j!=='object'||Array.isArray(j))return{err:'Fișierul nu este un backup Tensiunea Mea.'};if(!Array.isArray(j.patients))return{err:'Lipsește lista de pacienți. Nu este un backup Tensiunea Mea.'};
 const ids=new Set(j.patients.filter(p=>p&&p.id).map(p=>p.id));let bad=0;const g=(k,f)=>(Array.isArray(j[k])?j[k]:[]).filter(x=>{const ok=x&&typeof x==='object'&&x.id&&ids.has(x.pid)&&f(x);if(!ok)bad++;return ok});
 const out={...j,patients:j.patients.filter(p=>p&&p.id&&typeof p.name==='string'),bp:g('bp',x=>Number.isFinite(+x.sys)&&Number.isFinite(+x.dia)&&/^\d{4}-\d{2}-\d{2}$/.test(x.date||'')),meds:g('meds',x=>typeof x.name==='string'),intakes:g('intakes',x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date||''))};return{out,bad}}
function importFile(f){if(!f)return;const r=new FileReader();r.onload=()=>{let j;try{j=JSON.parse(r.result)}catch{return alert('Fișierul nu este JSON valid.')}const v=validate(j);if(v.err)return alert(v.err);const o=v.out;
 if(confirm(`Backup: ${o.patients.length} pacienți, ${o.bp.length} măsurători, ${o.meds.length} medicamente.\nÎn aplicație acum: ${data.patients.length} pacienți, ${data.bp.length} măsurători.${v.bad?`\n⚠ ${v.bad} înregistrări invalide vor fi ignorate.`:''}\n\nÎnlocuiești datele curente? Se creează automat un instantaneu de siguranță.`))Store.replace(o).then(()=>location.reload()).catch(e=>alert('Importul a eșuat: '+e.message))};r.readAsText(f)}
const slotOf=k=>{const[mid,t,d]=k.split('|'),m=data.meds.find(x=>x.id===mid);return m?{m,d,t}:null};
function preview(){const f=$('bf');if(!f)return;const s=+f.sys.value,d=+f.dia.value,pv=$('pv');if(!s||!d){pv.className='w pv';pv.textContent='Introdu valorile ca să vezi încadrarea.';return}if(s<=d||s<50||d<30){pv.className='w pv';pv.textContent='Verifică valorile introduse.';return}const c=catOf(s,d);pv.className='w pv on';pv.style.setProperty('--pc',c.c);pv.innerHTML=`<b>${c.n}</b><span>${c.d}</span>${s>=180||d>=120?`<em>${CRISIS}</em>`:''}`}
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-go]');if(!t)return;const d=t.dataset,fail=e=>alert('Nu a mers: '+(e.message||e)),sn=snapData();
 if(t.id==='burger')document.body.classList.toggle('open');else if(t.id==='theme'||t.id==='theme2'){document.body.classList.toggle('dark');try{localStorage.setItem('tm-theme',document.body.classList.contains('dark')?'d':'l')}catch{}}
 else if(d.go){tab=d.go;render();scrollTo(0,0)}
 else if(d.take){const s=slotOf(d.take);if(s){setIntake(s,'taken');save()}}else if(d.skip){const s=slotOf(d.skip);if(s){setIntake(s,'skipped');save()}}else if(d.unset){const s=slotOf(d.unset);if(s){setIntake(s,null);save()}}
 else if(d.prn){const m=data.meds.find(x=>x.id===d.prn);data.intakes.push({id:id(),pid,medId:m.id,date:today(),slot:null,at:nowT(),status:'taken',prn:true});toast(m.name+' notat la '+nowT());save()}
 else if(d.hm){histMode=d.hm;render()}else if(d.hd!==undefined){histDays=+d.hd;render()}
 else if(d.pd!==undefined){planDate=d.pd==='0'?today():addD(planDate,+d.pd);render()}
 else if(d.rt){R.tab=d.rt;render()}else if(d.rd!==undefined){R.days=+d.rd;render()}
 else if(d.ebp){const x=data.bp.find(y=>y.id===d.ebp);ask('Editează măsurătoarea',bpFields(x),v=>{if(!bpOk(v))return false;Object.assign(x,bpObj(v));save()})}
 else if(d.dbp){const x=data.bp.find(y=>y.id===d.dbp);if(!confirm(`Ștergi măsurătoarea ${x.sys}/${x.dia} din ${fmtD(x.date)} ${x.time}?`))return;data.bp=data.bp.filter(y=>y!==x);save();toast('Măsurătoare ștearsă',()=>restoreData(sn))}
 else if(d.din){data.intakes=data.intakes.filter(i=>i.id!==d.din);save();toast('Înregistrare ștearsă',()=>restoreData(sn))}
 else if(d.med)medForm(d.med==='new'?null:data.meds.find(m=>m.id===d.med));
 else if(d.dmed){const m=data.meds.find(x=>x.id===d.dmed);if(!confirm(`Ștergi „${m.name}” și toate bifările lui? Pentru a-l opri doar, editează-l și setează data de oprire.`))return;data.meds=data.meds.filter(x=>x!==m);data.intakes=data.intakes.filter(i=>i.medId!==m.id);save();toast('Medicament șters',()=>restoreData(sn))}
 else if(d.pat){const p=d.pat==='new'?null:P(d.pat);ask(p?'Editează pacientul':'Pacient nou',patFields(p||{}),v=>{if(!v.name.trim())return false;const x=p||{id:id()};savePat(x,v);if(!p){data.patients.push(x);setPid(x.id)}save()})}
 else if(d.dpat){const p=P(d.dpat);if(!confirm(`Ștergi pacientul „${p.name}” cu toate măsurătorile, pastilele și bifările lui? Se poate anula imediat după.`))return;data.patients=data.patients.filter(x=>x!==p);data.bp=data.bp.filter(x=>x.pid!==p.id);data.meds=data.meds.filter(x=>x.pid!==p.id);data.intakes=data.intakes.filter(x=>x.pid!==p.id);if(pid===p.id)setPid(data.patients[0]?.id||null);save();toast('Pacient șters',()=>restoreData(sn))}
 else if(d.ics){if(!data.meds.some(m=>m.pid===pid&&!m.prn)&&!(P().remind||[]).length)return alert('Nu ai medicamente cu ore sau ore de memento pentru măsurare.');dl('memento-'+P().name.replace(/\W+/g,'-')+'.ics',icsText(),'text/calendar')}
 else if(d.act==='print')print();else if(d.act==='backup'){data.lastBackup=today();Store.save(data).catch(()=>{});dl('backup-tensiunea-mea-'+today()+'.json',JSON.stringify(data),'application/json');render()}
 else if(d.act==='csvbp'){const[f,to]=rng();dl('tensiune-'+P().name+'-'+today()+'.csv','﻿'+['Data;Ora;Sistolica;Diastolica;Puls;Incadrare;Brat;Pozitie;Nota',...pbp(pid,f,to).map(x=>[x.date,x.time,x.sys,x.dia,x.pulse||'',catOf(x.sys,x.dia).n,ARM[x.arm]||'',POS[x.pos]||'',x.note||''].map(csvq).join(';'))].join('\r\n'),'text/csv')}
 else if(d.act==='csvin'){const[f,to]=rng();dl('pastile-'+P().name+'-'+today()+'.csv','﻿'+['Data;Medicament;Doza;Ora programata;Ora luarii;Stare',...data.intakes.filter(i=>i.pid===pid&&i.date>=f&&i.date<=to).sort((a,b)=>a.date.localeCompare(b.date)).map(i=>{const m=data.meds.find(x=>x.id===i.medId)||{};return[i.date,m.name||'',m.dose||'',i.slot||'la nevoie',i.at||'',i.status==='taken'?'luata':'sarita'].map(csvq).join(';')})].join('\r\n'),'text/csv')}
 else if(d.snap){if(confirm('Restaurezi acest instantaneu? Datele curente se salvează întâi într-un instantaneu nou.'))Store.restore(d.snap).then(()=>location.reload()).catch(fail)}
 else if(d.sec==='pass')ask('Activează parola',[{n:'p1',l:'Parolă (minim 6 caractere)',t:'password'},{n:'p2',l:'Repetă parola',t:'password'}],v=>{if(v.p1.length<6){alert('Parola are minim 6 caractere.');return false}if(v.p1!==v.p2){alert('Parolele nu coincid.');return false}if(!confirm('Datele vor fi criptate. Dacă uiți parola, le poți recupera doar din backup JSON. Ai făcut backup?'))return false;stor=null;Store.enablePass(v.p1).then(()=>{toast('Parola a fost activată');render()}).catch(fail)})
 else if(d.sec==='face')ask('Activează Face ID',[{n:'p1',l:'Parolă de rezervă (minim 6 caractere)',t:'password'},{n:'p2',l:'Repetă parola',t:'password'}],v=>{if(v.p1.length<6){alert('Parola are minim 6 caractere.');return false}if(v.p1!==v.p2){alert('Parolele nu coincid.');return false}Store.enableFace(v.p1).then(()=>{toast('Face ID activat');render()}).catch(fail)})
 else if(d.sec==='chg')ask('Schimbă parola',[{n:'o',l:'Parola actuală',t:'password'},{n:'p1',l:'Parola nouă (minim 6)',t:'password'},{n:'p2',l:'Repetă parola nouă',t:'password'}],v=>{if(v.p1.length<6||v.p1!==v.p2){alert('Parola nouă trebuie să aibă minim 6 caractere și să coincidă.');return false}Store.changePass(v.o,v.p1).then(()=>toast('Parola a fost schimbată')).catch(fail)})
 else if(d.sec==='off'){if(confirm('Dezactivezi blocarea? Datele vor fi stocate necriptat.'))Store.disable().then(()=>{toast('Blocare dezactivată');render()}).catch(fail)}
 else if(d.sec==='lock')void Store.lock();
 else if(d.sec==='health')Store.health().then(r=>{healthRes=r;render()}).catch(fail);
 else if(d.sec==='persist')Store.persist().then(ok=>{stor=null;toast(ok?'Stocare persistentă activată':'Browserul nu a acordat stocare persistentă');render()})});
document.addEventListener('change',e=>{const i=e.target.id;if(i==='psel'){setPid(e.target.value);render()}else if(i==='lockafter')Store.setLockAfter(+e.target.value).then(()=>toast('Salvat'));else if(i==='imp'){importFile(e.target.files[0]);e.target.value=''}else if(i==='rf'){R.from=e.target.value||R.from;render()}else if(i==='rt'){R.to=e.target.value||R.to;render()}});
document.addEventListener('input',e=>{if(e.target.closest('#bf'))preview()});
document.addEventListener('submit',e=>{const f=e.target.id;if(f!=='pf'&&f!=='bf')return;e.preventDefault();const v=Object.fromEntries(new FormData(e.target));
 if(f==='pf'){if(!v.name.trim())return;const p={id:id()};savePat(p,{...v,times:[],notes:''});data.patients.push(p);setPid(p.id);save()}
 else{if(!bpOk(v))return;const x={id:id(),pid,...bpObj(v)};data.bp.push(x);tab='home';save();toast(`Salvat: ${x.sys}/${x.dia} · ${catOf(x.sys,x.dia).n}`);if(isCrisis(x))setTimeout(()=>alert(CRISIS),200)}});
try{if(localStorage.getItem('tm-theme')==='d')document.body.classList.add('dark')}catch{}
if(Store.notes().length)setTimeout(()=>toast('⚠ '+Store.notes()[0]),600);
render();window.__booted=true;document.getElementById('splash')?.remove();window.__bmDown&&window.__bmDown();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
